-- Optional GSTIN captured during counter registration. Format validation only.
alter table public.merchants add column gstin text check (gstin is null or gstin ~ '^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$');
create or replace function register_merchant(p_input jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare m merchants;t jsonb;begin if not exists(select 1 from profiles where id=auth.uid() and role='merchant') then raise exception 'Partner account required';end if;if length(trim(p_input->>'name'))<2 then raise exception 'Business name required';end if;insert into merchants(owner_id,slug,name,gstin,category,building,address,city,state,pin,campus,is_on_campus,hours,avg_prep_minutes,supports_pickup,supports_dine_in,pay_at_counter_enabled) values(auth.uid(),lower(regexp_replace(p_input->>'name','[^a-zA-Z0-9]+','-','g'))||'-'||substr(gen_random_uuid()::text,1,5),p_input->>'name',nullif(upper(trim(p_input->>'gstin')),''),p_input->>'category',p_input->>'building',p_input->>'address',p_input->>'city',p_input->>'state',p_input->>'pin',p_input->>'campus',(p_input->>'is_on_campus')::boolean,p_input->>'hours',(p_input->>'avg_prep_minutes')::int,(p_input->>'supports_pickup')::boolean,(p_input->>'supports_dine_in')::boolean,(p_input->>'pay_at_counter_enabled')::boolean) returning * into m;
 for t in select * from jsonb_array_elements(coalesce(p_input->'tables','[]')) loop insert into merchant_tables(id,merchant_id,label,enabled) values((t->>'id')::uuid,m.id,t->>'label',true);end loop;return to_jsonb(m);end$$;
